import{_ as o,c as i,o as a,j as n,Y as s,t as r}from"./chunks/framework.D-NV0Bun.js";const k=JSON.parse('{"title":"git-clean | x-cmd man (git man1) | Remove untracked files from the working tree","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-clean - Remove untracked files from the working tree","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-clean | x-cmd man (git man1) | Remove untracked files from the working tree"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-clean - Remove untracked files from the working tree"}]]},"headers":[],"params":{"isMan":true,"man":"git-clean","category":"git man1","desc":"Remove untracked files from the working tree"},"relativePath":"git/man1/git-clean.md","filePath":"git/man1/[man].md"}'),l={name:"git/man1/git-clean.md"},c={class:"visually-hidden"};function h(t,e,p,d,u,g){return a(),i("div",null,[n("h1",c,r(t.$params.man),1),e[0]||(e[0]=s(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-clean - Remove untracked files from the working tree</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-d] [-f] [-i] [-n] [-q] [-e </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pattern</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] [-x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> -X] [--] [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pathspec</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...]</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Cleans the working tree by recursively removing files that are not under version control, starting from the current directory.</p><p>Normally, only files unknown to Git are removed, but if the <strong>-x</strong> option is specified, ignored files are also removed. This can, for example, be useful to remove all build products.</p><p>If any optional <strong>&lt;pathspec&gt;...</strong> arguments are given, only those paths that match the pathspec are affected.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>-d</p><blockquote><p>Normally, when no &lt;pathspec&gt; is specified, git clean will not recurse into untracked directories to avoid removing too much. Specify -d to have it recurse into such directories as well. If a &lt;pathspec&gt; is specified, -d is irrelevant; all untracked files matching the specified paths (with exceptions for nested git directories mentioned under <strong>--force</strong>) will be removed.</p></blockquote><p>-f, --force</p><blockquote><p>If the Git configuration variable clean.requireForce is not set to false, <em>git clean</em> will refuse to delete files or directories unless given -f or -i. Git will refuse to modify untracked nested git repositories (directories with a .git subdirectory) unless a second -f is given.</p></blockquote><p>-i, --interactive</p><blockquote><p>Show what would be done and clean files interactively. See &quot;Interactive mode&quot; for details.</p></blockquote><p>-n, --dry-run</p><blockquote><p>Don&#39;t actually remove anything, just show what would be done.</p></blockquote><p>-q, --quiet</p><blockquote><p>Be quiet, only report errors, but not the files that are successfully removed.</p></blockquote><p>-e &lt;pattern&gt;, --exclude=&lt;pattern&gt;</p><blockquote><p>Use the given exclude pattern in addition to the standard ignore rules (see <strong>gitignore</strong>(5)).</p></blockquote><p>-x</p><blockquote><p>Don&#39;t use the standard ignore rules (see <strong>gitignore</strong>(5)), but still use the ignore rules given with <strong>-e</strong> options from the command line. This allows removing all untracked files, including build products. This can be used (possibly in conjunction with <em>git restore</em> or <em>git reset</em>) to create a pristine working directory to test a clean build.</p></blockquote><p>-X</p><blockquote><p>Remove only files ignored by Git. This may be useful to rebuild everything from scratch, but keep manually created files.</p></blockquote><h2 id="interactive-mode" tabindex="-1">INTERACTIVE MODE <a class="header-anchor" href="#interactive-mode" aria-label="Permalink to &quot;INTERACTIVE MODE&quot;">​</a></h2><p>When the command enters the interactive mode, it shows the files and directories to be cleaned, and goes into its interactive command loop.</p><p>The command loop shows the list of subcommands available, and gives a prompt &quot;What now&gt; &quot;. In general, when the prompt ends with a single <em>&gt;</em>, you can pick only one of the choices given and type return, like this:</p><blockquote><pre><code>   ** * Commands** *
        1: clean                2: filter by pattern    3: select by numbers
        4: ask each             5: quit                 6: help
    What now&gt; 1
</code></pre></blockquote><p>You also could say <strong>c</strong> or <strong>clean</strong> above as long as the choice is unique.</p><p>The main command loop has 6 subcommands.</p><p>clean</p><blockquote><p>Start cleaning files and directories, and then quit.</p></blockquote><p>filter by pattern</p><blockquote><p>This shows the files and directories to be deleted and issues an &quot;Input ignore patterns&gt;&gt;&quot; prompt. You can input space-separated patterns to exclude files and directories from deletion. E.g. &quot;*.c *.h&quot; will excludes files end with &quot;.c&quot; and &quot;.h&quot; from deletion. When you are satisfied with the filtered result, press ENTER (empty) back to the main menu.</p></blockquote><p>select by numbers</p><blockquote><p>This shows the files and directories to be deleted and issues an &quot;Select items to delete&gt;&gt;&quot; prompt. When the prompt ends with double <em>&gt;&gt;</em> like this, you can make more than one selection, concatenated with whitespace or comma. Also you can say ranges. E.g. &quot;2-5 7,9&quot; to choose 2,3,4,5,7,9 from the list. If the second number in a range is omitted, all remaining items are selected. E.g. &quot;7-&quot; to choose 7,8,9 from the list. You can say <em>*</em> to choose everything. Also when you are satisfied with the filtered result, press ENTER (empty) back to the main menu.</p></blockquote><p>ask each</p><blockquote><p>This will start to clean, and you must confirm one by one in order to delete items. Please note that this action is not as efficient as the above two actions.</p></blockquote><p>quit</p><blockquote><p>This lets you quit without do cleaning.</p></blockquote><p>help</p><blockquote><p>Show brief usage of interactive git-clean.</p></blockquote><h2 id="configuration" tabindex="-1">CONFIGURATION <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;CONFIGURATION&quot;">​</a></h2><p>Everything below this line in this section is selectively included from the <strong>git-config</strong>(1) documentation. The content is the same as what&#39;s found there:</p><p>clean.requireForce</p><blockquote><p>A boolean to make git-clean do nothing unless given -f, -i or -n. Defaults to true.</p></blockquote><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>gitignore</strong>(5)</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,51))])}const f=o(l,[["render",h]]);export{k as __pageData,f as default};
